45:     public static function getNewCaseNumber($processId)
46:     {
47:         $process = Process::findOrFail($processId);
48:         if ($process->case_prefix) {
49:             $start = config('workflow.caseStartValue', 1);
50:             $numbering = CaseNumbering::firstOrCreate(
51:                 ['prefix' => $process->case_prefix],
52:                 ['count' => $start - 1]
53:             );
54:             $numbering->count = $numbering->count + 1;
55:             $numbering->save();
56: 
57:             return $process->case_prefix . '-' . str_pad($numbering->count, 4, '0', STR_PAD_LEFT);
58:         }
59: 
60:         if (config('workflow.caseNumberingPerCategory')) {
61:             $category = ProcessController::getById($processId)?->category;
62:             $processIds = Process::where('category', $category)->pluck('id');
63:             $lastNumber = Cases::whereIn('process_id', $processIds)->orderByRaw('CAST(number AS UNSIGNED) DESC')->first()?->number;
64:         } elseif (config('workflow.caseNumberingPerProcess')) {
65:             $lastNumber = Cases::where('process_id', $processId)->orderByRaw('CAST(number AS UNSIGNED) DESC')->first()?->number;
66:         } else {
67:             $lastNumber = Cases::orderByRaw('CAST(number AS UNSIGNED) DESC')->first()?->number;
68:         }
69:         $newNumber = $lastNumber ? $lastNumber + 1 : config('workflow.caseStartValue');
70:         return $newNumber;
71:     }
