312:     public static function executeNextTask($task, $caseId, array &$executedTaskIds = null)
313:     {
314:         try {
315:             if (!$task) {
316:                 return null;
317:             }
318: 
319:             if ($executedTaskIds === null) {
320:                 $executedTaskIds = [];
321:             }
322: 
323:             if (in_array($task->id, $executedTaskIds, true)) {
324:                 return null;
325:             }
326: 
327:             $executedTaskIds[] = $task->id;
328: 
329:             if ($task->type == 'form') {
330:                 if ($task->assignment_type == 'normal' or $task->assignment_type == null) {
331:                     $taskActors = TaskActorController::getActorsByTaskId($task->id);
332:                     foreach ($taskActors as $ta) {
333:                         $actors = collect();
334:                         if ($ta->role_id) {
335:                             $actors = User::where('role_id', $ta->role_id)->pluck('id');
336:                         } else {
337:                             $actors->push($ta->actor);
338:                         }
339:                         foreach ($actors as $actor) {
340:                             $inbox = InboxController::create($task->id, $caseId, $actor, 'new');
341:                             SendPushNotification::dispatch(
342:                                 $inbox->actor,
343:                                 'کار جدید',
344:                                 'کار جدید بهتون ارجاع داده شد: ' . $inbox->case_name,
345:                                 route('simpleWorkflow.inbox.view', $inbox->id)
346:                             );
347:                         }
348:                     }
349:                     // echo json_encode($taskActors);
350:                 }
351:                 if ($task->assignment_type == 'dynamic') {
352:                     $taskActors = TaskActorController::getDynamicTaskActors($task->id, $caseId)->pluck('actor');
353:                     foreach ($taskActors as $actor) {
354:                         $inbox = InboxController::create($task->id, $caseId, $actor, 'new');
355:                         SendPushNotification::dispatch(
356:                             $inbox->actor,
357:                             'کار جدید',
358:                             'کار جدید بهتون ارجاع داده شد: ' . $inbox->case_name,
359:                             route('simpleWorkflow.inbox.view', $inbox->id)
360:                         );
361:                     }
362:                 }
363:                 if ($task->assignment_type == 'public') {
364:                     $taskActors = TaskActorController::getActorsByTaskId($task->id);
365:                     foreach ($taskActors as $ta) {
366:                         $actors = collect();
367:                         if ($ta->role_id) {
368:                             $actors = User::where('role_id', $ta->role_id)->pluck('id');
369:                         } else {
370:                             $actors->push($ta->actor);
371:                         }
372:                         foreach ($actors as $actor) {
373:                             $inbox = InboxController::create($task->id, $caseId, $actor, 'done');
374:                         }
375:                     }
376:                     // $inbox = InboxController::create($task->id, $caseId, Auth::id(), 'new');
377:                 }
378:             }
379:             if ($task->type == 'script') {
380:                 $script = ScriptController::getById($task->executive_element_id);
381:                 $result = ScriptController::runScript($task->executive_element_id, $caseId);
382:                 if ($result) {
383:                     return response()->json([
384:                         'status' => 400,
385:                         'msg' => $result
386:                     ]);
387:                 }
388:                 if ($task->next_element_id) {
389:                     $nextTask = TaskController::getById($task->next_element_id);
390:                     $result = self::executeNextTask($nextTask, $caseId, $executedTaskIds);
391:                     if($result == 'break'){
392:                         return 'break';
393:                     }
394:                     if ($result) {
395:                         return $result;
396:                     }
397:                 }
398:                 $taskChildren = $task->children();
399:                 foreach ($taskChildren as $task) {
400:                     $result = self::executeNextTask($task, $caseId, $executedTaskIds);
401:                     if($result == 'break'){
402:                         return 'break';
403:                     }
404:                     if ($result) {
405:                         return $result;
406:                     }
407:                 }
408:             }
409:             if ($task->type == 'condition') {
410:                 $condition = ConditionController::getById($task->executive_element_id);
411:                 $result = ConditionController::runCondition($task->executive_element_id, $caseId);
412:                 // print($result);
413: 
414:                 if ($result) {
415:                     $nextTask = $condition->nextIfTrue();
416:                     if ((bool)$nextTask) {
417:                         $result = self::executeNextTask($nextTask, $caseId, $executedTaskIds);
418:                         if ($result && $result !== 'break') {
419:                             return $result;
420:                         }
421:                     } else {
422:                         if ($task->next_element_id) {
423:                             $nextTask = TaskController::getById($task->next_element_id);
424:                             $result = self::executeNextTask($nextTask, $caseId, $executedTaskIds);
425:                             if ($result && $result !== 'break') {
426:                                 return $result;
427:                             }
428:                         }
429:                         $taskChildren = $task->children();
430:                         foreach ($taskChildren as $childTask) {
431:                             $result = self::executeNextTask($childTask, $caseId, $executedTaskIds);
432:                             if ($result && $result !== 'break') {
433:                                 return $result;
434:                             }
435:                         }
436:                     }
437:                 }
438:             }
439:             if ($task->type == 'end') {
440:                 $inbox = InboxController::create($task->id, $caseId, null, 'done');
441:                 return 'break';
442:             }
443:             if ($task->type == 'timed_condition') {
444:                 // 1. بررسی اینکه زمان‌بندی استاتیک است یا داینامیک
445:                 $delayMinutes = 0;
446:                 if ($task->timing_type == 'static') {
447:                     // فیلدی مانند `timing_value` در تسک ذخیره شده است (مثلاً 10 دقیقه)
448:                     Log::info('Timing value: ' . $task->timing_value);
449:                     $delayMinutes = intval($task->timing_value);
450:                 } elseif ($task->timing_type == 'dynamic') {
451:                     // متغیر مثل "nexttime" از پرونده گرفته می‌شود
452:                     $key = $task->timing_key_name;
453:                     $variable = CaseController::getById($caseId)->getVariable($key);
454:                     Log::info('Variable: ' . $variable);
455:                     $delayMinutes = (int)$variable;
456:                     
457:                 }
458: 
459:                 if ($delayMinutes > 0) {
460:                     Log::info('Delay minutes: ' . $delayMinutes);
461:                     $taskChildren = $task->children();
462:                     foreach ($taskChildren as $task) {
463:                         ExecuteNextTaskWithDelay::dispatch($task, $caseId)->delay(now()->addMinutes($delayMinutes));
464:                     }
465:                 } else {
466:                     // اگر زمان‌بندی معتبر نبود، فوراً اجرا شود یا خطا داده شود
467:                     return response()->json([
468:                         'status' => 400,
469:                         'msg' => 'زمان‌بندی معتبر نیست'
470:                     ]);
471:                 }
472: 
473:                 return 'break';
