21:     {
22:         return response()->json([
23:             'ok' => true,
24:             'forms' => $this->collections(Form::class, 'id', 'name'),
25:             'users' => $this->collections(\App\Models\User::class, 'id', 'name'),
26:             'roles' => $this->collections(Role::class, 'id', 'name'),
27:             'assignmentTypes' => [
