35:     public function get(Request $request, string $doc, string $element): JsonResponse
36:     {
37:         if (! $this->storageEnabled()) {
38:             return response()->json(['ok' => false, 'message' => Lang::field('Storing is disabled.')], 403);
39:         }
40: 
41:         $config = $this->config->find($doc, $element);
42: 
43:         if ($config === null) {
44:             return response()->json(['ok' => false, 'message' => Lang::field('Task configuration was not found.')], 404);
45:         }
46: 
47:         return response()->json(['ok' => true, 'config' => $config]);
48:     }
