51:     {
52:         if (! $this->storageEnabled()) {
53:             return response()->json(['ok' => false, 'message' => Lang::field('Storing is disabled.')], 403);
54:         }
55: 
56:         $rules = [];
57: 
58:         foreach (DiagramConfigStore::FIELDS as $field) {
59:             $rules[$field] = ['nullable', 'string', 'max:255'];
60:         }
61: 
62:         $data = $request->validate($rules);
63: 
64:         if (! preg_match(DiagramRepository::ID_PATTERN, $doc)) {
65:             return response()->json(['ok' => false, 'message' => Lang::field('Invalid diagram ID.')], 422);
66:         }
