 *
 * @return array<int, string>
 */
public static function scriptTaskIds(string $xml): array
{
    try {
        $parsed = self::parse($xml);
    } catch (InvalidArgumentException) {
        return [];
    }
    $ids = [];
    foreach ($parsed['script_tasks'] as $task) {
        $id = (string) ($task['element_id'] ?? '');
        if ($id !== '') {
            $ids[] = $id;
        }
    }
    return $ids;
}

